sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var _apptDetails = new AppointmentUtils();
var _patinetAppt = _apptDetails.fetchPatientAppointments('0ec304b847a6a610629597da116d4372')
if (!_patinetAppt.hasNext()) {
  gs.print("No appointments found for patient.");
} else {
  while (_patinetAppt.next()) {
	gs.print("-----Appointment-----")
  	gs.print("Appointment Date: " + _patinetAppt.u_appointment_date);
   	gs.print("Doctor: " + _patinetAppt.u_doctor.getDisplayValue());        
	gs.print("Status: " + _patinetAppt.u_status);        
	gs.print("-----");
	}
}

var _checkStatus = _apptDetails.checkAppointmentStatus('APT0001040');
gs.print(_checkStatus);
gs.print("------")

var _appointDetails = _apptDetails.getAppointmentDetails('APT0001040');
gs.print("-----Appointment Details-----")
gs.print("Appointment Date: " + _appointDetails.u_appointment_date);
gs.print("Doctor: " + _appointDetails.u_doctor.getDisplayValue());        
gs.print("Status: " + _appointDetails.u_status);        
gs.print("-----");

var _appointDetailsByDate = _apptDetails.getAppointmentDetailsByDate('2025-07-03');

        gs.print("-----Appointment Details By Date-----");
        gs.print("Appointment ID: " + _appointDetailsByDate.number);
        gs.print("Doctor: " + _appointDetailsByDate.u_doctor.getDisplayValue());
        gs.print("Status: " + _appointDetailsByDate.u_status);
        gs.print("------------------");




var _appointDetailsByDepartment = _apptDetails.getAppointmentDetailsByDepartment('Pediatrics')
if (!_appointDetailsByDepartment.hasNext()) {
  gs.print("No appointment found for that department.");
}
else { while(_appointDetailsByDepartment.next()){
	gs.print("-----Appointment Details By Department-----")
	gs.print("Appointment ID: " + _appointDetailsByDepartment.number);
	gs.print("Doctor: " + _appointDetailsByDepartment.u_doctor.getDisplayValue());        
	gs.print("Status: " + _appointDetailsByDepartment.u_status);        
	gs.print("-----");
}
}



})(current, previous);
